function clone(x){return JSON.parse(JSON.stringify(x))}
function deepMerge(base,incoming){
 if(Array.isArray(base))return Array.isArray(incoming)?incoming:base;
 if(base&&typeof base==='object'){const out={...base};if(incoming&&typeof incoming==='object')for(const [k,v]of Object.entries(incoming)){if(['__proto__','constructor','prototype'].includes(k))throw Error('Propriedade de dados não permitida');out[k]=Object.hasOwn(base,k)?deepMerge(base[k],v):v;}return out;}
 return incoming===undefined?base:incoming;
}
function normalizeState(x){
 FCCCore.validateData(x||{});x=deepMerge(clone(seed),x||{});x.version=SCHEMA_VERSION;
 for(const it of x.inventory){it.qty=Number(it.qty??1);it.location=it.location||'';it.expiry=it.expiry||'';it.review=it.review||'';it.priority=it.priority||'Normal';it.custom=!!it.custom;}
 for(const p of x.people||[])p.contact=p.contact||'';
 for(const r of x.research||[]){r.pico=r.pico||'';r.grade=r.grade||'';r.bias=r.bias||'';}
 x.meta=x.meta||{};x.meta.schemaVersion=SCHEMA_VERSION;x.meta.lastBackup=x.meta.lastBackup||'';return x;
}
function loadState(){
 let raw=FCCStore.getItem(USER_KEY);if(!raw)for(const k of LEGACY_KEYS){raw=FCCStore.getItem(k);if(raw)break;}
 state=normalizeState(raw?FCCCore.parseJSON(raw):clone(seed));
 const cp=FCCStore.getItem(CONTENT_KEY);contentPack=cp?deepMerge(clone(DEFAULT_CONTENT),FCCCore.parseJSON(cp)):clone(DEFAULT_CONTENT);
}
function save(){
 if(!FCCStore.status().unlocked)throw Error('Desbloqueia o cofre antes de guardar dados.');
 state.meta=state.meta||{};state.meta.lastSaved=new Date().toISOString();
 const saved=FCCStore.setItem(USER_KEY,JSON.stringify(state));saved.catch(e=>FCCUI.notify(e.message,'error'));return saved;
}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function safeUrl(v){
 try{const u=new URL(String(v||''),location.href);return (u.protocol==='http:'||u.protocol==='https:')?u.href:''}catch(e){return ''}
}
function uid(p='x'){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function toast(message){if(FCCStore.status().pending)FCCStore.flush().then(()=>FCCUI.notify(message)).catch(e=>FCCUI.notify(e.message,'error'));else FCCUI.notify(message);}
function openModal(id){return FCCUI.open(id);} function closeModal(){return FCCUI.close();}
function go(page){return window.FCCNavigation?.navigate(page)||false;}
function subtab(page,id){return window.FCCNavigation?.navigate(page,{sub:id})||false;}
function openClin(key){return window.FCCNavigation?.navigate('clinical',{sub:'clin-'+key})||false;}
function saveNote(k,id){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('saveNote',[...arguments]);state.notes[k]=document.getElementById(id).value;save();toast('Guardado')}
function renderHome(){
 for(const id of ['homeHealth','homePrep','homeAlerts'])document.getElementById(id)?.replaceChildren();
 const notes=document.getElementById('homeNotes');if(notes)notes.value='';
}


