infDrug.addEventListener('change',()=>{infDU.value=drugDefaults[infDrug.value]||'mcgkgmin'});
function addPreset(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addPreset',[...arguments]);if(!preName.value||!(+preAmt.value>0)||!(+preVol.value>0))return;state.presets.unshift({id:uid('pr'),name:preName.value,amount:+preAmt.value,unit:preUnit.value,vol:+preVol.value,du:preDU.value});save();renderPresets()}
function renderPresets(){presetList.innerHTML=state.presets.length?'':'<div class="item"><span>Sem preparações guardadas.</span></div>';state.presets.forEach(x=>presetList.innerHTML+=`<div class="item"><div><strong>${esc(x.name)}</strong><br><span>${esc(x.amount)} ${esc(x.unit)} / ${esc(x.vol)} mL</span></div><div class="row"><button class="btn small" onclick="usePreset('${esc(x.id)}')">Usar</button><button class="btn small" onclick="delPreset('${esc(x.id)}')">×</button></div></div>`)}
function usePreset(id){const x=state.presets.find(p=>p.id===id);if(!x)return;infDrug.value=x.name;infAmount.value=x.amount;infAmountUnit.value=x.unit;infVol.value=x.vol;infDU.value=x.du;FCCClinical.clear(['infResult'],'Preparação alterada. Confirma os dados e calcula novamente.');}function delPreset(id){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('delPreset',[...arguments]);state.presets=state.presets.filter(x=>x.id!==id);save();renderPresets()}

/* VENT / ABG / ECG */
function pbw(sex,h){const inch=h/2.54;return sex==='male'?50+2.3*(inch-60):45.5+2.3*(inch-60)}
function acid(ph,co,hc){if(!(ph>0&&co>0&&hc>0))return '';if(ph<7.35){if(co>45&&hc<22)return'Acidose mista provável';if(co>45)return'Acidose respiratória predominante';if(hc<22)return'Acidose metabólica predominante';return'Acidemia'}if(ph>7.45){if(co<35&&hc>26)return'Alcalose mista provável';if(co<35)return'Alcalose respiratória predominante';if(hc>26)return'Alcalose metabólica predominante';return'Alcalemia'}if((co>45&&hc>26)||(co<35&&hc<22))return'Compensação/distúrbio misto possível';return'Próximo do equilíbrio'}
function analyzeVent(){if(!FCCClinical.validate('analyzeVent'))return;
 const h=+vHeight.value,V=+vVt.value,R=+vRR.value,pe=+vPEEP.value,tpe=+vTotalPEEP.value,pp=+vPplat.value,pk=+vPpeak.value,fi=+vFiO2.value,spo=+vSpO2.value,ph=+vPH.value,co=+vCO2.value,o=+vO2.value,hc=+vHCO3.value,lac=+vLac.value;
 const passive=vPassive.checked, plateauValid=vPlateauValid.checked, mode=vMode.value;
 let P=NaN,vtkg=NaN,dp=NaN,cs=NaN,pf=NaN;const met=[],ad=[];
 if(h>0){P=pbw(vSex.value,h);met.push(['PBW',P.toFixed(1)+' kg'])}
 if(V>0&&P>0){vtkg=V/P;met.push(['Vt/PBW',vtkg.toFixed(1)+' mL/kg'])}
 if(V>0&&R>0)met.push(['Volume minuto',(V*R/1000).toFixed(1)+' L/min']);
 const effectivePEEP=vTotalPEEP.value.trim()!==''?tpe:pe;
 if(pp>0&&plateauValid&&passive){
   dp=pp-effectivePEEP;met.push(['Driving pressure',dp.toFixed(1)+' cmH₂O']);
   if(dp>0&&V>0){cs=V/dp;met.push(['Cstat',cs.toFixed(1)+' mL/cmH₂O'])}
 }else if(pp>0){met.push(['Pplat/ΔP','Interpretação limitada'])}
 if(o>0&&fi>0&&fi<=100){pf=o/(fi/100);met.push(['P/F',pf.toFixed(0)])}
 if(ph>0)met.push(['Ácido-base',acid(ph,co,hc)]);
 ventMetrics.innerHTML=met.map(x=>`<div class="item"><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span></div>`).join('');
 if(vtkg>8)ad.push(['bad','Vt >8 mL/kg PBW','Rever estratégia protetora, sobretudo em ARDS/risco VILI.']);
 else if(vtkg>=4&&vtkg<=8)ad.push(['ok','Vt 4–8 mL/kg PBW','Faixa protetora habitual; individualizar ao contexto.']);
 if(pp>30&&plateauValid&&passive)ad.push(['bad','Pplat >30 cmH₂O','Rever Vt, PEEP, compliance e contexto, garantindo pausa inspiratória válida.']);
 if(dp>15)ad.push(['warn','Driving pressure >15','Marcador fisiológico/observacional; rever mecânica e estratégia sem usar o valor como alvo isolado.']);
 if(pk>0&&pp>0&&mode==='VC-AC'&&plateauValid&&passive&&pk-pp>10)ad.push(['warn','Ppeak−Pplat elevado em VC','Sugere componente resistiva: secreções, broncospasmo, TOT/circuito e fluxo.']);
 if(pk>0&&pp>0&&mode!=='VC-AC')ad.push(['ok','Ppeak−Pplat não interpretado como resistência','Esse gradiente depende do modo/fluxo e não é aplicado automaticamente fora de VC-AC.']);
 if(!passive||!plateauValid)ad.push(['warn','Mecânica com validade limitada','Pplat, ΔP e Cstat exigem condições de medição adequadas e ausência de esforço significativo para interpretação estática.']);
 if(tpe>pe&&tpe>0)ad.push(['warn','PEEP total > PEEP set','Auto-PEEP/intrinsic PEEP é possível; integrar curva expiratória e manobra válida.']);
 if(pf>0&&pf<100)ad.push(['bad','P/F <100','Hipoxemia muito importante; integrar definição/causa e estratégia respiratória.']);
 if(ph>0&&ph<7.20&&co>45)ad.push(['bad','Acidémia + hipercapnia','Rever ventilação minuto/espaço morto sem ultrapassar limites protetores.']);
 if(spo>0&&fi>=60&&spo<90)ad.push(['bad','SpO₂ baixa com FiO₂ elevada','Confirmar sinal, circuito/via aérea e deterioração aguda.']);
 if(lac>=4)ad.push(['bad','Lactato ≥4','Integrar perfusão, tendência e causas não hipóxicas.']);
 ventAdvice.innerHTML=(ad.length?ad:[['ok','Sem red flags automáticas','Rever curvas, sincronia, causa e tendência.']]).map(x=>`<div class="${x[0]==='bad'?'redflag':'advice'}"><strong>${esc(x[1])}</strong><br>${esc(x[2])}</div>`).join('');
 ventSummary.innerHTML=`<div class="big">${acid(ph,co,hc)||'Análise calculada'}</div><div class="subtext">${isFinite(P)?'PBW '+P.toFixed(1)+' kg · ':''}${isFinite(vtkg)?'Vt '+vtkg.toFixed(1)+' mL/kg · ':''}${isFinite(pf)?'P/F '+pf.toFixed(0):''}</div>`;
}
function analyzeECG(){if(!FCCClinical.validate('analyzeECG'))return;const r=+eRate.value,q=+eQRS.value,pr=+ePR.value,qt=+eQTc.value,reg=eReg.value,p=eP.value,st=eST.value,sym=eSymptoms.value,le=eLeads.value;const o=[];if(sym==='yes')o.push(['bad','Instabilidade/sintomas','Priorizar ABC, monitorização e algoritmo urgente conforme quadro.']);if(reg==='Irregularmente irregular'&&p==='Ausentes/não visíveis')o.push(['ok','Compatível com FA','Confirmar traçado e contexto.']);if(r>=150&&reg==='Regular'&&q>0&&q<120)o.push(['warn','Taquicardia regular estreita','TSV possível; considerar flutter 2:1 e sinusal.']);if(r>100&&q>=120)o.push(['bad','Taquicardia de QRS largo','TV é diagnóstico crítico a assumir/excluir; estabilidade dita urgência.']);if(pr>200)o.push(['warn','PR prolongado','Compatível com BAV 1.º grau se cada P conduz.']);if(qt>=500)o.push(['bad','QTc ≥500 ms','Rever fármacos e K/Mg/Ca; risco de torsades.']);if(st==='elev'||st==='both')o.push(['bad','Elevação ST '+esc(le),'Se nova/contígua e contexto isquémico, ativar avaliação ACS urgente; considerar diferenciais.']);if(st==='dep'||st==='both')o.push(['warn','Depressão ST '+esc(le),'Pode representar isquemia/padrão recíproco.']);ecgResult.innerHTML=(o.length?o:[['ok','Sem classificação automática','Completar eixo, morfologia, ST/T e comparação prévia.']]).map(x=>`<div class="${x[0]==='bad'?'redflag':'advice'}"><strong>${esc(x[1])}</strong><br>${esc(x[2])}</div>`).join('')}
function loadECG(c){eSymptoms.value='no';eST.value='none';eLeads.value='';if(c==='af'){eRate.value=145;eReg.value='Irregularmente irregular';eP.value='Ausentes/não visíveis';eQRS.value=90}if(c==='svt'){eRate.value=185;eReg.value='Regular';eP.value='Ausentes/não visíveis';eQRS.value=88}if(c==='vt'){eRate.value=170;eReg.value='Regular';eP.value='Ausentes/não visíveis';eQRS.value=168;eSymptoms.value='yes'}if(c==='inf'){eRate.value=72;eReg.value='Regular';eP.value='Presentes antes de cada QRS';eQRS.value=92;eST.value='elev';eLeads.value='II, III, aVF';eSymptoms.value='yes'}analyzeECG()}
function calcHemo(){if(!FCCClinical.validate('calcHemo'))return;const s=+hSBP.value,d=+hDBP.value,h=+hHR.value;if(!(s>0&&d>0&&h>0))return;const m=(s+2*d)/3;hemoResult.innerHTML=`<div class="big">MAP ${m.toFixed(0)}</div><div class="subtext">Shock Index ${(h/s).toFixed(2)} · Modified ${(h/m).toFixed(2)}</div>`}function calcPF(){if(!FCCClinical.validate('calcPF'))return;const p=+pfO2.value,f=+pfFi.value;if(!(p>0&&f>0))return;const x=p/(f/100);pfResult.innerHTML=`<div class="big">${x.toFixed(0)}</div><div class="subtext">P/F isolado não diagnostica ARDS.</div>`}
function analyzeABG(){if(!FCCClinical.validate('analyzeABG'))return;const ph=+aPH.value,co=+aCO2.value,hc=+aHCO3.value,na=+aNa.value,cl=+aCl.value,al=+aAlb.value;const o=[];if(ph>0&&co>0&&hc>0)o.push(`<div class="advice"><strong>${acid(ph,co,hc)}</strong><br>pH ${ph} · PaCO₂ ${co} · HCO₃ ${hc}</div>`);if(na>0&&cl>0&&hc>0){const ag=na-cl-hc,c=isFinite(al)&&al>0?ag+2.5*(4-al):NaN;o.push(`<div class="advice"><strong>Anion gap ${ag.toFixed(1)}</strong><br>${isFinite(c)?'Corrigido '+c.toFixed(1):'Sem correção por albumina.'}</div>`);const w=1.5*hc+8;if(ph<7.35&&hc<22)abgExtra.innerHTML=`<div class="big">Winter ${w.toFixed(1)} ±2</div><div class="subtext">${co>0?(co>w+2?'PaCO₂ acima do esperado → componente respiratório acidótico.':co<w-2?'PaCO₂ abaixo → componente alcalótico.':'Compensação aproximada esperada.'):'—'}</div>`}abgResult.innerHTML=o.join('')}
function analyzeElectrolytes(){if(!FCCClinical.validate('analyzeElectrolytes'))return;const na=+elNa.value,k=+elK.value,ca=+elCa.value,cr=+elCr.value,o=[];if(k>=6)o.push(['bad','K⁺ ≥6,0','Hipercaliemia marcada: ECG/monitorização e protocolo urgente conforme clínica.']);else if(k>5)o.push(['warn','K⁺ elevado','Confirmar hemólise, ECG/tendência e função renal.']);else if(k>0&&k<2.5)o.push(['bad','K⁺ <2,5','Hipocaliemia marcada; risco elétrico/neuromuscular.']);else if(k>0&&k<3.5)o.push(['warn','K⁺ baixo','Rever Mg, perdas e fármacos.']);if(na>0&&(na<=120||na>=160))o.push(['bad','Disnatremia marcada','Avaliar tonicidade, sintomas, cronicidade e limites de correção.']);else if(na>0&&(na<135||na>145))o.push(['warn','Na fora da faixa habitual','Integrar volume/tonicidade/causa.']);if(ca>0&&ca<.9)o.push(['warn','Ca ionizado baixo','Integrar sintomas, QT, citrato/transfusão e Mg.']);if(cr>1.5)o.push(['warn','Creatinina elevada','Comparar baseline e diurese; valor isolado não define AKI.']);elecResult.innerHTML=(o.length?o:[['ok','Sem alertas automáticos','Usar intervalos de referência locais.']]).map(x=>`<div class="${x[0]==='bad'?'redflag':'advice'}"><strong>${esc(x[1])}</strong><br>${esc(x[2])}</div>`).join('')}
function calcCorrectedNa(){if(!FCCClinical.validate('calcCorrectedNa'))return;const n=+cnNa.value,g=+cnGlu.value,f=+cnFactor.value;if(!(n>0&&g>0))return;const c=n+f*Math.max(0,(g-100)/100);cnResult.innerHTML=`<div class="big">${c.toFixed(1)} mmol/L</div><div class="subtext">Estimativa com fator ${f}/100 mg/dL.</div>`}

/* DRUGS, SEPSIS, STROKE, SEDATION */
function renderDrugs(){if(window.FCCMedications)return;const grid=document.getElementById('drugGrid');if(grid)grid.textContent='Abre Medicação para carregar o catálogo.';}
function analyzeSepsis(){return FCCClinical.sepsis();}
function analyzeStroke(){if(!FCCClinical.validate('analyzeStroke'))return;const h=+stHours.value,n=+stNIHSS.value,s=+stSBP.value,d=+stDBP.value,b=stBleed.value,l=stLVO.value,a=stDOAC.value,o=[];if(b==='yes')o.push(['bad','Hemorragia identificada','Sair do algoritmo IVT isquémico e ativar via ICH.']);else{if(b==='unknown')o.push(['bad','Imagem pendente','TC/imagem urgente antes de decisão reperfusão.']);if(h>0&&h<=4.5)o.push(['ok','Dentro da janela padrão IVT','Elegibilidade depende de imagem, défice, PA e contraindicações.']);else if(h>4.5)o.push(['warn','>4,5 h','Seleção por imagem avançada/MT pode continuar relevante.']);if((s>=185||d>=110)&&h<=4.5)o.push(['bad','PA ≥185/110','Acima da referência ESO pré-IVT; seguir protocolo local.']);if(a==='yes')o.push(['bad','DOAC <48 h','Complexidade/contraindicação importante para IVT em guideline ESO salvo contextos específicos.']);if(l==='yes')o.push(['bad','Suspeita LVO','Acelerar angioimagem/MT; IVT elegível não deve atrasar trombectomia.']);if(n>=6)o.push(['ok','NIHSS significativo','Integrar défice incapacitante e imagem vascular.'])}strokeResult.innerHTML=o.map(x=>`<div class="${x[0]==='bad'?'redflag':'advice'}"><strong>${esc(x[1])}</strong><br>${esc(x[2])}</div>`).join('')||'<div class="advice">Introduz os dados.</div>'}
function updateRASS(){const m={4:'Combativo',3:'Muito agitado',2:'Agitado',1:'Inquieto',0:'Alerta e calmo','-1':'Sonolento','-2':'Sedação ligeira','-3':'Sedação moderada','-4':'Sedação profunda','-5':'Não despertável'},v=+rass.value;rassResult.innerHTML=`<div class="big">RASS ${v>0?'+':''}${v}</div><div class="subtext">${esc(m[v])}</div>`}function calcCPOT(){if(!FCCClinical.validate('calcCPOT'))return;const t=+c1.value+ +c2.value+ +c3.value+ +c4.value;cpotResult.innerHTML=`<div class="big">${t}/8</div><div class="subtext">${t>=3?'Dor comportamental clinicamente relevante é possível; correlacionar.':'Reavaliar em movimento/procedimento.'}</div>`}function calcBPS(){if(!FCCClinical.validate('calcBPS'))return;const t=+b1.value+ +b2.value+ +b3.value;bpsResult.innerHTML=`<div class="big">${t}/12</div><div class="subtext">Score mínimo 3; usar tendência/contexto.</div>`}

/* ALS / CRRT / FLUID / SCALES */
function fmt(sec){return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}function startCode(){if(codeStart)return;codeStart=Date.now();codeInt=setInterval(()=>codeTimer.textContent=fmt(Math.floor((Date.now()-codeStart)/1000)),1000);codeMark('Timer iniciado')}function codeMark(n){if(!codeStart){codeStart=Date.now();codeInt=setInterval(()=>codeTimer.textContent=fmt(Math.floor((Date.now()-codeStart)/1000)),1000)}const t=fmt(Math.floor((Date.now()-codeStart)/1000));codeLog.unshift({n,t});codeEvents.innerHTML=codeLog.map(x=>`<div class="item"><strong>${esc(x.n)}</strong><span>${esc(x.t)}</span></div>`).join('')}function resetCode(){clearInterval(codeInt);codeStart=null;codeInt=null;codeLog=[];codeTimer.textContent='00:00';codeEvents.innerHTML=''}
function calcCRRT(){if(!FCCClinical.validate('calcCRRT'))return;const w=+crWt.value,d=+crD.value||0,r=+crR.value||0,u=+crU.value||0;if(!(w>0))return;const e=d+r+u;crResult.innerHTML=`<div class="big">${(e/w).toFixed(1)} mL/kg/h</div><div class="subtext">Efluente bruto ${e.toFixed(0)} mL/h · dose entregue depende de downtime/pré-diluição.</div>`}
function addFluid(){
 if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addFluid',[...arguments]);
 try{const n=(id,min,positive=false)=>FCCCore.number(document.getElementById(id).value,id,{min,exclusiveMin:positive});
 state.fluidRecords.unshift({id:uid('fl'),date:flDate.value||new Date().toISOString(),wt:n('flWt',0,true),input:n('flIn',0),output:n('flOut',0),urine:n('flUrine',0),hours:n('flHours',0,true)});save();renderFluid();}catch(e){FCCUI.notify(e.message,'error');}
}function renderFluid(){fluidTable.innerHTML='';state.fluidRecords.forEach(x=>{const bal=x.input-x.output,u=x.wt>0?x.urine/x.wt/x.hours:NaN;fluidTable.innerHTML+=`<tr><td>${new Date(x.date).toLocaleString('pt-PT')}</td><td>${esc(x.input)}</td><td>${esc(x.output)}</td><td>${bal>=0?'+':''}${bal}</td><td>${esc(isFinite(u)?u.toFixed(2)+' mL/kg/h':x.urine)}</td><td><button class="btn small" onclick="delFluid('${esc(x.id)}')">×</button></td></tr>`})}function delFluid(id){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('delFluid',[...arguments]);state.fluidRecords=state.fluidRecords.filter(x=>x.id!==id);save();renderFluid()}
function calcGCS(){if(!FCCClinical.validate('calcGCS'))return;const e=+gE.value,v=+gV.value,m=+gM.value;gResult.innerHTML=`<div class="big">${e+v+m}/15</div><div class="subtext">E${e} V${v} M${m}</div>`}
function calcCrCl(){if(!FCCClinical.validate('calcCrCl'))return;const a=+cgAge.value,w=+cgWt.value,c=+cgCr.value;if(!(a>0&&w>0&&c>0))return;let x=(140-a)*w/(72*c);if(cgSex.value==='female')x*=.85;cgResult.innerHTML=`<div class="big">${x.toFixed(0)} mL/min</div><div class="subtext">Cockcroft-Gault; seleção de peso depende do contexto.</div>`}function calcOsm(){if(!FCCClinical.validate('calcOsm'))return;const n=+osNa.value,g=+osGlu.value||0,b=+osBun.value||0;if(!(n>0))return;const x=2*n+g/18+b/2.8;osResult.innerHTML=`<div class="big">${x.toFixed(1)} mOsm/kg</div>`}function calcBody(){if(!FCCClinical.validate('calcBody'))return;const w=+boWt.value,h=+boHt.value;if(!(w>0&&h>0))return;const bmi=w/((h/100)**2),bsa=Math.sqrt(w*h/3600);boResult.innerHTML=`<div class="big">BMI ${bmi.toFixed(1)}</div><div class="subtext">BSA ${bsa.toFixed(2)} m² · Mosteller.</div>`}

/* CASES / CHECKLISTS / ISBAR */
const CASES=[
{title:'Choque séptico',text:'72 kg, infeção provável, MAP 54, lactato 4,6 e pele marmoreada. Prioridade?',choices:['Aguardar nova gasimetria','Ressuscitação/hemodinâmica imediata + acelerar antimicrobianos/source control','Apenas diurético','Reduzir monitorização'],correct:1,why:'SSC 2026: sépsis/choque é emergência; tratamento, hemodinâmica, antimicrobianos e source control devem ser acelerados.'},
{title:'Ventilação protetora',text:'ARDS, PBW 60 kg, Vt 540 mL, Pplat 32, PEEP 10. O que rever?',choices:['Vt ≈9 mL/kg + Pplat elevada','PEEP 10 isolada','FC desconhecida','Sexo'],correct:0,why:'Vt/PBW alto e Pplat >30 são red flags para rever estratégia.'},
{title:'AVC + LVO',text:'Défice incapacitante, 2 h, TC sem hemorragia e suspeita LVO. Circuito?',choices:['Esperar 24 h','Acelerar angioimagem/reperfusão; IVT elegível não deve atrasar MT','PA <120 sempre','Alta'],correct:1,why:'LVO deve acelerar trombectomia; IVT elegível não deve atrasar MT.'},
{title:'QRS largo',text:'FC 175 regular, QRS 170 ms, hipotensão e alteração consciência.',choices:['TSV benigna','TV crítica até prova em contrário e instabilidade determina urgência','FA lenta','Repetir ECG amanhã'],correct:1,why:'Taquicardia de QRS largo + instabilidade exige abordagem urgente.'},
{title:'Hipercaliemia',text:'K 6,7 em subida + QRS a alargar.',choices:['Sem urgência','ECG/monitorização + protocolo urgente de estabilização/deslocação/remoção conforme causa','Água oral','Suspender ECG'],correct:1,why:'Hipercaliemia marcada com alteração elétrica é emergência.'}
];
function newCase(){const caseSource=(contentPack.cases&&contentPack.cases.length?contentPack.cases:CASES);currentCase=caseSource[Math.floor(Math.random()*caseSource.length)];caseArea.innerHTML=`<div class="advice"><strong>${esc(currentCase.title)}</strong><br>${esc(currentCase.text)}</div><div class="stack">${currentCase.choices.map((c,i)=>`<button class="casechoice" onclick="answerCase(${i},this)">${String.fromCharCode(65+i)}. ${esc(c)}</button>`).join('')}</div><div id="caseFeedback"></div>`}function answerCase(i,b){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('answerCase',[...arguments]);if(b.dataset.done)return;document.querySelectorAll('.casechoice').forEach(x=>x.dataset.done='1');state.caseStats.total++;if(i===currentCase.correct){state.caseStats.correct++;b.classList.add('correct')}else{b.classList.add('wrong');document.querySelectorAll('.casechoice')[currentCase.correct].classList.add('correct')}caseFeedback.innerHTML=`<div class="advice"><strong>Feedback</strong><br>${esc(currentCase.why)}</div>`;save();updateCaseScore()}function updateCaseScore(){caseScore.textContent=state.caseStats.correct+'/'+state.caseStats.total}function resetCase(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('resetCase',[...arguments]);state.caseStats={correct:0,total:0};save();updateCaseScore();newCase()}
const CHECKS={icu:[['Identificação/motivo','Diagnóstico e objetivos imediatos'],['ABCDE','Neurológico, perfusão, ventilação'],['Via aérea/TOT/cuff','Posição, fixação e plano'],['Ventilador/GSA','Modo, Vt/PBW, PEEP, FiO₂, pressões'],['Acessos/dispositivos','CVC, arterial, drenos, SNG, algália'],['Perfusões alto risco','Fármaco, concentração, dose, via'],['Sedação/dor/delirium','RASS, CPOT/BPS, objetivo'],['Pele/prevenção','Pressão, mobilização, dispositivos'],['Balanço/renal','Diurese, creatinina, TSR'],['Família/comunicação','Contacto, informação e plano'],['Profilaxias/segurança','VTE, alergias, isolamento'],['Plano/pendentes','Prioridades, exames, escalada']],transport:[['Identificação/destino/equipa','Confirmar doente e objetivo'],['Via aérea segura','Fixação, cuff, aspiração, plano'],['Oxigénio','Autonomia com margem'],['Ventilador transporte','Parâmetros e bateria'],['Monitorização','ECG, SpO₂, PA, capnografia se indicada'],['Acessos/perfusões','Fixação, volumes, bombas'],['Fármacos emergência','Conforme risco/protocolo'],['Drenos/linhas','Fixação e coletores'],['Documentação','Pedido/resultados'],['ISBAR','Plano de deterioração e responsabilidades']]};
function renderChecks(){const checklistSource=contentPack.checklists||CHECKS;for(const type of ['icu','transport']){const root=document.getElementById(type==='icu'?'icuChecklist':'transportChecklist');root.innerHTML=checklistSource[type].map((x,i)=>`<label class="check"><input type="checkbox" ${state.checklistState[type][i]?'checked':''} onchange="toggleCheck('${type}',${i},this.checked)"><div><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span></div></label>`).join('')}}function toggleCheck(t,i,v){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('toggleCheck',[...arguments]);state.checklistState[t][i]=v;save()}function resetChecklist(t){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('resetChecklist',[...arguments]);state.checklistState[t]={};save();renderChecks()}
function generateISBAR(){isbarOut.textContent=`I — IDENTIFICAÇÃO\n${iI.value}\n\nS — SITUAÇÃO\n${iS.value}\n\nB — BACKGROUND\n${iB.value}\n\nA — ASSESSMENT\n${iA.value}\n\nR — RECOMMENDATION\n${iR.value}`}function copyISBAR(){navigator.clipboard?.writeText(isbarOut.textContent).then(()=>toast('ISBAR copiado'))}

/* EMERGENCY */
function renderEmergency(){renderInventory();renderPeople();renderLocations();scLoc.innerHTML=state.locations.map(x=>`<option>${esc(x.name)}</option>`).join('');emNotes.value=state.notes.emergency||''}
function renderInventory(){
 const cats=[...new Set(state.inventory.map(x=>x.category))].sort(),previousCat=invCat.value;
 invCat.innerHTML='<option value="">Todas categorias</option>'+cats.map(c=>`<option>${esc(c)}</option>`).join('');
 if(cats.includes(previousCat))invCat.value=previousCat;
 const q=(invSearch.value||'').toLowerCase(),cat=invCat.value,today=new Date();
 const a=state.inventory.filter(x=>(!cat||x.category===cat)&&(!q||x.name.toLowerCase().includes(q)));
 inventoryGrid.innerHTML=a.map(x=>{
   const expired=x.expiry&&new Date(x.expiry)<today, review=x.review&&new Date(x.review)<today;
   return `<div class="card"><div class="row"><input type="checkbox" style="width:18px" ${x.done?'checked':''} onchange="toggleInv('${esc(x.id)}',this.checked)"><div><h3>${esc(x.name)}</h3><p>${esc(x.category)}</p></div><div class="spacer"></div>${expired?'<span class="badge bad">Expirado</span>':review?'<span class="badge warn">Rever</span>':''}</div>
   <div class="form2" style="margin-top:7px"><label>Qtd<input type="number" value="${esc(x.qty)}" onchange="updateInv('${esc(x.id)}','qty',this.value)"></label><label>Local<input value="${esc(x.location||'')}" onchange="updateInv('${esc(x.id)}','location',this.value)"></label><label>Validade<input type="date" value="${esc(x.expiry||'')}" onchange="updateInv('${esc(x.id)}','expiry',this.value)"></label><label>Rever em<input type="date" value="${esc(x.review||'')}" onchange="updateInv('${esc(x.id)}','review',this.value)"></label></div>${x.custom?`<div class="actions"><button class="btn small" onclick="deleteCustomInventory('${esc(x.id)}')">Remover item personalizado</button></div>`:''}</div>`
 }).join('');
 const d=state.inventory.filter(x=>x.done).length,t=state.inventory.length,p=t?Math.round(d/t*100):0;
 invCount.textContent=a.length+' visíveis';prepBadge.textContent=p+'% · '+d+'/'+t;homePrep.innerHTML=p+'% <small>'+d+'/'+t+' itens</small>';
}
function addCustomInventory(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addCustomInventory',[...arguments]);
 if(!ciName.value.trim()||!ciCat.value.trim())return toast('Nome e categoria são obrigatórios');
 state.inventory.push({id:uid('inv'),name:ciName.value.trim(),category:ciCat.value.trim(),qty:+ciQty.value||1,location:ciLoc.value.trim(),done:false,expiry:ciExpiry.value,review:ciReview.value,priority:ciPriority.value,custom:true});
 save();closeModal('inventoryModal');renderInventory();toast('Item adicionado');
}
function deleteCustomInventory(id){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('deleteCustomInventory',[...arguments]);state.inventory=state.inventory.filter(x=>x.id!==id);save();renderInventory()}
function exportInventoryCSV(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('exportInventoryCSV',[...arguments]);
 const cols=['name','category','qty','location','done','expiry','review','priority'];
 dl([cols.join(';'),...state.inventory.map(x=>cols.map(c=>'"'+String(x[c]??'').replace(/"/g,'""')+'"').join(';'))].join('\\n'),'emergency-inventory.csv','text/csv;charset=utf-8')
}
function toggleInv(id,v){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('toggleInv',[...arguments]);state.inventory.find(x=>x.id===id).done=v;save();renderInventory()}function updateInv(id,k,v){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('updateInv',[...arguments]);const x=state.inventory.find(x=>x.id===id);x[k]=k==='qty'?+v:v;save()}
function renderPeople(){peopleList.innerHTML=state.people.map(x=>`<div class="item"><div><strong>${esc(x.name)}</strong><br><span>${esc(x.role)} · ${esc(x.location)}</span></div><input style="max-width:170px" placeholder="Contacto" value="${esc(x.contact||'')}" onchange="setPersonContact('${esc(x.id)}',this.value)"></div>`).join('')}function setPersonContact(id,v){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('setPersonContact',[...arguments]);state.people.find(x=>x.id===id).contact=v;save()}
function renderLocations(){locationList.innerHTML=state.locations.map(x=>`<div class="item"><div><strong>${esc(x.name)}</strong><br><span>${esc(x.type)}</span></div><input style="max-width:210px" placeholder="Ponto encontro" value="${esc(x.meet||'')}" onchange="setMeet('${esc(x.id)}',this.value)"></div>`).join('')}function setMeet(id,v){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('setMeet',[...arguments]);state.locations.find(x=>x.id===id).meet=v;save()}
function generateScenario(){const t=scType.value,l=scLoc.value,c=scComms.value,i=scInjury.value;const steps=[];if(i==='yes')steps.push('ABCDE e controlo de ameaças imediatas antes de deslocação.');if(t==='Sismo')steps.push('Proteção imediata durante o abalo; após cessar, avaliar estrutura/gás/eletricidade e saídas.');if(t==='Blackout')steps.push('Confirmar extensão da falha; preservar bateria, iluminação e água; evitar elevadores.');if(t.includes('Incêndio'))steps.push('Evacuar por rota segura sem elevadores; afastar-se de fumo e seguir autoridades.');if(t==='Inundação')steps.push('Evitar pisos baixos/água em movimento; desligar energia apenas se seguro.');steps.push(`Local: ${l}. Confirmar ponto de encontro e estado dos familiares.`);steps.push(c==='yes'?'Usar telemóvel/Meshtastic com mensagens curtas e estado/local.':'Ativar plano sem rede: ponto de encontro + horários de tentativa + mensageiro físico se seguro.');scenarioOut.innerHTML=steps.map((x,n)=>`<div class="advice"><strong>${n+1}</strong> · ${esc(x)}</div>`).join('')}

/* COMMS */
function renderComms(){renderNodes();renderTelemetry();renderTests()}
function renderNodes(){
 nodeList.innerHTML=state.nodes.map(n=>`<div class="card"><div class="row"><h3>${esc(n.name)}</h3><div class="spacer"></div><span class="badge good">${esc(n.status)}</span></div><p>${esc(n.hardware)} · ${esc(n.band)} · ${esc(n.sensor)}</p>
 <div class="form2" style="margin-top:8px"><label>Etiqueta<input value="${esc(n.label||n.name)}" onchange="setNode('${esc(n.id)}','label',this.value)"></label><label>Local<input value="${esc(n.location)}" onchange="setNode('${esc(n.id)}','location',this.value)"></label><label>Firmware<input value="${esc(n.firmware||'')}" onchange="setNode('${esc(n.id)}','firmware',this.value)"></label><label>Bateria mAh<input type="number" value="${esc(n.batteryCapacity||'')}" onchange="setNode('${esc(n.id)}','batteryCapacity',this.value)"></label></div>
 <div class="list"><div class="item"><span>Antena</span><strong>${esc(n.antenna)}</strong></div></div></div>`).join('')
}
function setNode(id,k,v){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('setNode',[...arguments]);const n=state.nodes.find(x=>x.id===id);if(!n)return;n[k]=k==='batteryCapacity'?Number(v)||'':v;save()}
function exportCommsCSV(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('exportCommsCSV',[...arguments]);
 const rows=['type;date;node/from;to;temp;humidity;pressure;battery;rssi;snr;result'];
 for(const x of state.telemetry)rows.push(`telemetry;"${esc(x.date)}";"${esc(x.node)}";;${esc(x.temp)};${esc(x.hum)};${esc(x.press)};${esc(x.bat)};;;`);
 for(const x of state.commsTests)rows.push(`test;"${esc(x.date)}";"${String(x.from).replace(/"/g,'""')}";"${String(x.to).replace(/"/g,'""')}";;;;;${esc(x.rssi)};${esc(x.snr)};"${esc(x.result)}"`);
 dl(rows.join('\\n'),'meshtastic-logs.csv','text/csv;charset=utf-8')
}
function nullableNumber(v){return String(v).trim()===''?null:Number(v)}
function addTelemetry(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addTelemetry',[...arguments]);state.telemetry.unshift({id:uid('te'),node:envNode.value,date:envDate.value||new Date().toISOString(),temp:nullableNumber(envTemp.value),hum:nullableNumber(envHum.value),press:nullableNumber(envPress.value),bat:nullableNumber(envBat.value)});save();renderTelemetry()}function renderTelemetry(){teleTable.innerHTML='';state.telemetry.forEach(x=>teleTable.innerHTML+=`<tr><td>${new Date(x.date).toLocaleString('pt-PT')}</td><td>${esc(x.node)}</td><td>${x.temp!==null&&isFinite(x.temp)?x.temp:'—'}</td><td>${x.hum!==null&&isFinite(x.hum)?x.hum:'—'}</td><td>${x.press!==null&&isFinite(x.press)?x.press:'—'}</td><td>${x.bat!==null&&isFinite(x.bat)?x.bat:'—'}</td><td><button class="btn small" onclick="delTele('${esc(x.id)}')">×</button></td></tr>`);teleLatest.innerHTML=['NODE-01','NODE-02','NODE-03'].map(n=>{const x=state.telemetry.find(t=>t.node===n);return `<div class="tele"><span>${n}</span><b>${x&&x.temp!==null&&isFinite(x.temp)?x.temp+' °C':'—'}</b><span>${x&&x.hum!==null&&isFinite(x.hum)?x.hum+'% · ':''}${x&&x.press!==null&&isFinite(x.press)?x.press+' hPa':''}</span></div>`}).join('')}function delTele(id){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('delTele',[...arguments]);state.telemetry=state.telemetry.filter(x=>x.id!==id);save();renderTelemetry()}
function calcFSPL(){if(!FCCClinical.validate('calcFSPL'))return;const d=+rfDist.value,f=+rfFreq.value;if(!(d>0&&f>0))return;const p=32.44+20*Math.log10(d)+20*Math.log10(f);rfPL.value=p.toFixed(1);rfResult.innerHTML=`<div class="big">${p.toFixed(1)} dB</div><div class="subtext">Free-space only.</div>`}function calcLink(){if(!FCCClinical.validate('calcLink'))return;const rx=+rfTx.value+ +rfGT.value+ +rfGR.value- +rfLoss.value- +rfPL.value,m=rx- +rfSens.value;linkResult.innerHTML=`<div class="big">${rx.toFixed(1)} dBm</div><div class="subtext">Margem teórica ${m.toFixed(1)} dB.</div>`}
function addTest(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addTest',[...arguments]);state.commsTests.unshift({id:uid('ct'),date:new Date().toISOString(),from:tFrom.value,to:tTo.value,rssi:+tRSSI.value,snr:+tSNR.value,result:tRes.value});save();renderTests()}function renderTests(){testList.innerHTML=state.commsTests.length?'':'<div class="item"><span>Sem testes.</span></div>';state.commsTests.forEach(x=>testList.innerHTML+=`<div class="item"><div><strong>${esc(x.from)} → ${esc(x.to)}</strong><br><span>${new Date(x.date).toLocaleString('pt-PT')} · RSSI ${esc(x.rssi)} · SNR ${esc(x.snr)}</span></div><span class="badge">${esc(x.result)}</span></div>`)}

/* GARAGE */
function renderGarage(){afYear.value=state.vehicles.africa.year||'';afKm.value=state.vehicles.africa.km||'';afNotes.value=state.vehicles.africa.notes||'';poYear.value=state.vehicles.polaris.year||'';poUse.value=state.vehicles.polaris.usage||'';poNotes.value=state.vehicles.polaris.notes||'';renderMaint();renderCosts();renderMods();renderFuel();renderDocs()}function saveVehicles(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('saveVehicles',[...arguments]);state.vehicles.africa={year:+afYear.value||'',km:+afKm.value||'',notes:afNotes.value};state.vehicles.polaris={year:+poYear.value||'',usage:poUse.value,notes:poNotes.value};save();toast('Veículos guardados')}
function addMaint(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addMaint',[...arguments]);state.maintenance.unshift({id:uid('ma'),vehicle:mVeh.value,item:mItem.value,last:+mLast.value||0,interval:+mInt.value||0,date:mDate.value});save();renderMaint()}function renderMaint(){maintList.innerHTML=state.maintenance.length?'':'<div class="item"><span>Sem manutenção registada.</span></div>';state.maintenance.forEach(x=>{const next=x.last+x.interval,cur=x.vehicle==='Africa Twin'?(+state.vehicles.africa.km||0):0;maintList.innerHTML+=`<div class="item"><div><strong>${esc(x.vehicle)} · ${esc(x.item)}</strong><br><span>Última ${esc(x.last||'—')} · próxima ${next||'—'} ${cur&&next&&cur>=next?'· ATRASADA':''}</span></div><button class="btn small" onclick="delArr('maintenance','${esc(x.id)}',renderMaint)">×</button></div>`})}
function addCost(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addCost',[...arguments]);state.costs.unshift({id:uid('co'),vehicle:cVeh.value,cat:cCat.value,val:+cVal.value||0,date:cDate.value,desc:cDesc.value});save();renderCosts()}function renderCosts(){costList.innerHTML=state.costs.length?'':'<div class="item"><span>Sem despesas.</span></div>';state.costs.forEach(x=>costList.innerHTML+=`<div class="item"><div><strong>${esc(x.vehicle)} · ${esc(x.cat)}</strong><br><span>${esc(x.date)} · ${esc(x.desc)}</span></div><strong>${Number(x.val||0).toFixed(2)} €</strong></div>`)}
function addMod(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addMod',[...arguments]);state.mods.unshift({id:uid('mo'),vehicle:moVeh.value,name:moName.value,priority:moPri.value,price:+moPrice.value||'',link:moLink.value,status:moStatus.value});save();renderMods()}function renderMods(){modList.innerHTML=state.mods.map(x=>`<div class="item"><div><strong>${esc(x.vehicle)} · ${esc(x.name)}</strong><br><span>${esc(x.priority)} · ${esc(x.status)}${esc(x.price?' · '+x.price+' €':'')}</span></div>${safeUrl(x.link)?`<a class="btn small" target="_blank" rel="noopener" href="${esc(safeUrl(x.link))}">Link</a>`:''}</div>`).join('')}
function addFuel(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addFuel',[...arguments]);state.fuelRecords.unshift({id:uid('fu'),vehicle:fuVeh.value,date:fuDate.value,km:+fuKm.value||0,l:+fuL.value||0,cost:+fuCost.value||0,full:fuFull.value==='yes'});save();renderFuel()}function renderFuel(){
 fuelList.innerHTML=state.fuelRecords.length?'':'<div class="item"><span>Sem abastecimentos.</span></div>';
 state.fuelRecords.forEach(x=>fuelList.innerHTML+=`<div class="item"><div><strong>${esc(x.vehicle)} · ${Number(x.l||0).toFixed(2)} L</strong><br><span>${esc(x.date)} · ${esc(x.km||'—')} km · ${x.full?'cheio':'parcial'}</span></div><div class="row"><strong>${Number(x.cost||0).toFixed(2)} €</strong><button class="btn small" onclick="delArr('fuelRecords','${esc(x.id)}',renderFuel)">×</button></div></div>`);
 const a=state.fuelRecords.filter(x=>x.vehicle==='Africa Twin'&&x.full&&x.km>0).slice().sort((a,b)=>a.km-b.km);
 let cons=[];
 for(let i=1;i<a.length;i++){const km=a[i].km-a[i-1].km;if(km>0)cons.push(a[i].l/km*100)}
 fuelStats.textContent=cons.length?`Africa Twin · média ${ (cons.reduce((a,b)=>a+b,0)/cons.length).toFixed(2)} L/100 km`:'Consumo: aguarda ≥2 depósitos cheios';
}
function addDoc(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addDoc',[...arguments]);state.vehicleDocs.unshift({id:uid('do'),vehicle:dVeh.value,type:dType.value,exp:dExp.value,notes:dNotes.value});save();renderDocs()}function renderDocs(){docList.innerHTML=state.vehicleDocs.length?'':'<div class="item"><span>Sem documentos.</span></div>';state.vehicleDocs.forEach(x=>{const days=x.exp?Math.ceil((new Date(x.exp)-new Date())/86400000):null;docList.innerHTML+=`<div class="item"><div><strong>${esc(x.vehicle)} · ${esc(x.type)}</strong><br><span>${esc(x.exp||'sem validade')} · ${esc(x.notes)}</span></div>${days!==null?`<span class="badge ${days<30?'warn':'good'}">${days<0?'Expirado':days+' dias'}</span>`:''}</div>`})}
function delArr(k,id,fn){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('delArr',[...arguments]);state[k]=state[k].filter(x=>x.id!==id);save();fn()}

/* RESEARCH */
function vancouver(r){let s=(r.authors?r.authors+'. ':'')+r.title+'. '+(r.journal?r.journal+'. ':'')+(r.year?r.year+'.':'');if(r.doi)s+=' doi:'+r.doi+'.';else if(r.pmid)s+=' PMID:'+r.pmid+'.';return s}
function renderResearch(){const q=(resSearch.value||'').toLowerCase();const a=state.research.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q));researchGrid.innerHTML=a.map(r=>`<div class="card half"><div class="row"><span class="badge">${esc(r.topic)}</span><span class="badge">${esc(r.status)}</span><div class="spacer"></div><button class="btn small" onclick="delResearch('${esc(r.id)}')">×</button></div><h3 style="margin-top:8px">${esc(r.title)}</h3><p>${esc(r.authors||'')}${r.journal?' · '+esc(r.journal):''} · ${esc(r.year||'')}</p>${r.doi||r.pmid?`<p style="margin-top:5px">${r.doi?'DOI '+esc(r.doi):''} ${r.pmid?'PMID '+esc(r.pmid):''}</p>`:''}${r.pico?`<p style="margin-top:6px"><b>PICO:</b> ${esc(r.pico)}</p>`:''}${r.grade||r.bias?`<p style="margin-top:6px"><b>Evidência:</b> ${esc(r.grade||'—')} · <b>Viés:</b> ${esc(r.bias||'—')}</p>`:''}${r.summary?`<p style="margin-top:7px">${esc(r.summary)}</p>`:''}${r.why?`<div class="advice" style="margin-top:7px"><strong>Porque importa</strong><br>${esc(r.why)}</div>`:''}<div class="notice oknote" style="margin-top:7px"><strong>Vancouver</strong><br>${esc(vancouver(r))}</div><div class="actions">${r.url&&safeUrl(r.url)?`<a class="btn small" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(r.url))}">Fonte</a>`:''}<button class="btn small" onclick="editResearch('${esc(r.id)}')">Editar</button><button class="btn small" onclick="navigator.clipboard.writeText(vancouver(state.research.find(x=>x.id==='${esc(r.id)}')));toast('Vancouver copiado')">Copiar</button></div></div>`).join('')}
function openResearchNew(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('openResearchNew',[...arguments]);
 rEditId.value='';
 for(const id of ['rTitle','rTopic','rType','rYear','rAuthors','rJournal','rDoi','rPmid','rQuality','rUrl','rTags','rSummary','rWhy','rPico','rGrade','rBias','rCritical']){const el=document.getElementById(id);if(el)el.value=''}
 rStatus.value='Por ler';openModal('researchModal')
}
function editResearch(id){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('editResearch',[...arguments]);
 const r=state.research.find(x=>x.id===id);if(!r)return;rEditId.value=id;
 rTitle.value=r.title||'';rTopic.value=r.topic||'';rType.value=r.type||'';rYear.value=r.year||'';rAuthors.value=r.authors||'';rJournal.value=r.journal||'';rDoi.value=r.doi||'';rPmid.value=r.pmid||'';rQuality.value=r.quality||'';rStatus.value=r.status||'Por ler';rUrl.value=r.url||'';rTags.value=r.tags||'';rSummary.value=r.summary||'';rWhy.value=r.why||'';rPico.value=r.pico||'';rGrade.value=r.grade||'';rBias.value=r.bias||'';rCritical.value=r.critical||'';openModal('researchModal')
}
function addResearch(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('addResearch',[...arguments]);
 if(!rTitle.value)return;
 const data={title:rTitle.value,topic:rTopic.value,type:rType.value,year:+rYear.value||'',authors:rAuthors.value,journal:rJournal.value,doi:rDoi.value,pmid:rPmid.value,quality:rQuality.value,status:rStatus.value,url:rUrl.value,tags:rTags.value,summary:rSummary.value,why:rWhy.value,pico:rPico.value,grade:rGrade.value,bias:rBias.value,critical:rCritical.value};
 if(rEditId.value){const r=state.research.find(x=>x.id===rEditId.value);if(r)Object.assign(r,data)}
 else state.research.unshift({id:uid('r'),...data});
 rEditId.value='';save();closeModal('researchModal');renderResearch()
}
function delResearch(id){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('delResearch',[...arguments]);state.research=state.research.filter(x=>x.id!==id);save();renderResearch()}
function dl(text,name,type){const b=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}function exportResearchCSV(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('exportResearchCSV',[...arguments]);const cols=['title','authors','journal','year','topic','type','doi','pmid','quality','status','url','tags','summary','why','critical'];dl([cols.join(';'),...state.research.map(r=>cols.map(c=>'"'+String(r[c]??'').replace(/"/g,'""')+'"').join(';'))].join('\n'),'research.csv','text/csv;charset=utf-8')}function exportResearchRIS(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('exportResearchRIS',[...arguments]);const L=[];state.research.forEach(r=>{L.push('TY  - JOUR','TI  - '+r.title);if(r.authors)L.push('AU  - '+r.authors);if(r.journal)L.push('JO  - '+r.journal);if(r.year)L.push('PY  - '+r.year);if(r.doi)L.push('DO  - '+r.doi);if(r.pmid)L.push('AN  - PMID:'+r.pmid);if(r.url)L.push('UR  - '+r.url);L.push('ER  - ','')});dl(L.join('\n'),'research.ris','application/x-research-info-systems')}
function exportResearchBibTeX(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('exportResearchBibTeX',[...arguments]);
 const clean=s=>String(s||'').replace(/[{}]/g,'');
 const entries=state.research.map((r,i)=>{
  const key='fcc'+(r.year||'nd')+'_'+(i+1);
  const fields=[`title={${clean(r.title)}}`,r.authors?`author={${clean(r.authors)}}`:'',r.journal?`journal={${clean(r.journal)}}`:'',r.year?`year={${esc(r.year)}}`:'',r.doi?`doi={${clean(r.doi)}}`:'',r.url?`url={${clean(r.url)}}`:''].filter(Boolean);
  return `@article{${key},\n  ${fields.join(',\n  ')}\n}`
 });
 dl(entries.join('\n\n'),'research.bib','text/plain;charset=utf-8')
}

/* MASTER MAINTENANCE */
function sourceAgeDays(date){const d=new Date(date),now=new Date();return Math.floor((now-d)/86400000)}
function renderMaintenance(){
 const set=(id,value)=>{const e=document.getElementById(id);if(e)e.textContent=String(value);};
 set('appHealthVersion','MASTER 1.4.0');set('schemaHealth','v1 · cofre v2');set('contentHealth',contentPack?.version||'—');set('activePackVersion',contentPack?.version||'—');set('storageHealth',FCCStore.status().unlocked?'Cofre aberto':'Cofre bloqueado');
 set('backupHealth','A cópia completa é cifrada e inclui todos os módulos inventariados. Verifica sempre o ficheiro exportado.');
 const registry=document.getElementById('sourceRegistry');if(registry)registry.innerHTML=(contentPack.sources||[]).map(x=>'<div class="source-row"><div><b>'+esc(x.name)+'</b><p>'+esc(x.use||'')+' · revisão declarada na base: '+esc(x.verified||'não indicada')+'</p></div><a class="btn" target="_blank" rel="noopener noreferrer" href="'+esc(safeUrl(x.url))+'">Abrir fonte</a></div>').join('');
 const health=document.getElementById('dataHealth');if(health)health.textContent=FCCStore.status().unlocked?'Dados disponíveis no cofre deste separador.':'Desbloqueia o cofre para consultar ou exportar dados pessoais.';
}
function selfTestCalculations(){return FCCCore.selfTests();}
function runDiagnostics(){
 const all=FCCCore.selfTests();const ids=[...document.querySelectorAll('[id]')].map(x=>x.id);all.push({name:'Identificadores únicos',pass:new Set(ids).size===ids.length});
 const mods=Object.values(FCCModules.status());all.push({name:'Módulos carregados sem falha',pass:mods.every(x=>x.state!=='error')});
 diagnosticResults.innerHTML=all.map(x=>'<div class="item '+(x.pass?'testpass':'testfail')+'"><strong>'+(x.pass?'PASS':'FAIL')+' · '+esc(x.name)+'</strong></div>').join('');
 toast(all.every(x=>x.pass)?'Verificações executadas sem falhas. Não equivale a validação clínica.':'Há verificações a rever.');return all;
}
function exportBackup(){return FCCBackup.exportAll();}
