function importUpdatePack(file){return FCCBackup.importPack(file).catch(e=>FCCUI.notify(e.message,'error'));}
function exportActiveContentPack(){if(!FCCStore.status().unlocked)return FCCAccess.deferCall('exportActiveContentPack',[...arguments]);dl(JSON.stringify(contentPack,null,2),'FCC_UpdatePack_'+String(contentPack.version||'active').replaceAll('.','-')+'.json','application/json')}
